import React, { useState } from 'react';

const PerformanceDashboard = () => {
  const [metrics, setMetrics] = useState({
    lcp: 0,
    fid: 0,
    cls: 0
  });

  const updateMetrics = () => {
    setMetrics({
      lcp: Math.random() * 3000,
      fid: Math.random() * 100,
      cls: Math.random() * 0.25
    });
  };

  return (
    <div className="dashboard">
      <h1>Performance Dashboard</h1>
      <div className="metric-card">
        <h3>LCP</h3>
        <p>{metrics.lcp.toFixed(1)} ms</p>
        {/* Add LCP status indicator here */}
      </div>
      <div className="metric-card">
        <h3>FID</h3>
        <p>{metrics.fid.toFixed(1)} ms</p>
        {/* Add FID status indicator here */}
      </div>
      <div className="metric-card">
        <h3>CLS</h3>
        <p>{metrics.cls.toFixed(3)}</p>
        {/* Add CLS status indicator here */}
      </div>
      <button onClick={updateMetrics}>Update Metrics</button>
    </div>
  );
};
